"""Frozen constants copied unchanged from the existing intent protocol."""
TAXONOMY = {'api_usage': 'Requests concrete instructions for implementing functionality or using an API/tool.', 'discrepancy': 'Existing code behaves unexpectedly or does not work as intended; asks what is wrong.', 'errors': 'Asks to understand or fix an explicit error, exception, warning, or stack trace.', 'review': 'Requests evaluation, a better solution, optimization, best practice, or choosing between approaches.', 'conceptual': 'Requests explanation of concepts, behavior, limitations, or why/how something works.', 'api_change': 'Problem explicitly arises from API/version changes, deprecation, or compatibility between versions.', 'learning': 'Requests learning resources, tutorials, or documentation to learn independently, not merely a concrete solution.'}
EXCLUSIONS = {'api_usage': 'Require an expressed request for implementation steps or API use. Merely showing existing code is insufficient.', 'discrepancy': 'Require reported actual behavior that differs from intended behavior. A general request for implementation without an existing failure is insufficient.', 'errors': 'Require an explicit error/exception/warning/trace plus a request to understand or fix it. Wrong output without an explicit error is insufficient.', 'review': 'Require a request to evaluate alternatives, assess a solution, optimize, or improve a working approach. Merely asking to fix broken code is NOT review.', 'conceptual': 'Require an expressed request for an underlying principle, mechanism, meaning, or general limitation. Needing knowledge to solve a concrete task does NOT itself imply a conceptual request.', 'api_change': 'Require an explicit causal connection to a version change, deprecation or version compatibility. Merely naming an installed version is insufficient.', 'learning': 'Require a request for resources such as tutorials, documentation, courses or reading material. Being a beginner, wanting to understand a solution, or asking for a software library is NOT a request for learning resources.'}
